with open("region.fasta") as f:
    for line in f:
        if not line.startswith(">"):
            seq += line.strip()

comp = str.maketrans("ACGT","TGCA")
rc = seq.translate(comp)[::-1]

def find_orfs(s, label, minaa=50):
    res=[]
    for frame in range(3):
        i=frame
        start=None
        j=frame
        # walk codons
        while j+3<=len(s):
            c=s[j:j+3]
            if c in ("ATG",) and start is None:
                start=j
            if c in ("TAA","TAG","TGA"):
                if start is not None and (j-start)/3>=minaa:
                    res.append((start+1, j+2, (j-start)//3, s[start:j]))
                start=None
            j+=3
        if start is not None and (len(s)-start)//3>=minaa:
            res.append((start+1, len(s), (len(s)-start)//3, s[start:]))
    return res

print("FORWARD ORFs >=50 aa:")
for o in sorted(find_orfs(seq,"fwd")):
    print(f"  {o[0]}-{o[1]} ({o[2]} aa)")
print("REVERSE ORFs >=50 aa (coords in original):")
for o in sorted(find_orfs(rc,"rev")):
    # convert
    s0=len(seq)-o[1]+1
    s1=len(seq)-o[0]+1
    print(f"  {s0}-{s1} ({o[2]} aa)")
